using Check=std::function<void(bool,const char*)>;
struct Gate {HANDLE entered=CreateEvent(nullptr,TRUE,FALSE,nullptr),release=CreateEvent(nullptr,TRUE,FALSE,nullptr);~Gate(){SetEvent(release);CloseHandle(entered);CloseHandle(release);}void Worker(){SetEvent(entered);if(WaitForSingleObject(release,10000)!=WAIT_OBJECT_0)throw std::runtime_error("Owned gate timeout");}};
class Host final:public CFrameWnd {void PostNcDestroy()override{}};
struct Isolation {HHOOK hook=SetWindowsHookEx(WH_CBT,[](int code,WPARAM w,LPARAM l)->LRESULT{return code==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,code,w,l);},nullptr,GetCurrentThreadId());~Isolation(){UnhookWindowsHookEx(hook);}};
sct::core::DocumentState State(){sct::core::Image image;image.Create(96,72);sct::core::DocumentState state;state.base=std::make_shared<const sct::core::Image>(std::move(image));sct::core::Annotation box;box.tool=sct::core::Tool::Rectangle;box.rect={10,10,40,40};box.filled=true;box.color=RGB(255,0,0);state.objects.push_back(box);return state;}
void Atomic(Check check,const std::filesystem::path& dir){using namespace sct;CString error;const CString path=(dir/L"a").c_str();const std::vector<BYTE> old{1,7,2,9},replacement(2*1024*1024,42);std::vector<BYTE> read;
    check(services::WriteBytes(path,old,error),"owned prior target created");std::atomic_bool cancel{false};
    for(int phase=0;phase<=2;++phase){cancel=false;services::AtomicWriteFaults faults;faults.checkpoint=[&](int at){if(at==phase)cancel=true;};services::atomicWriteFaults=&faults;bool saved=false;{core::CancellationScope scope(cancel);saved=services::WriteBytes(path,replacement,error);}services::atomicWriteFaults=nullptr;
        check(!saved&&services::ReadBytes(path,read,error)&&read==old,"cancel at write/flush/publish keeps exact prior target bytes");check(!faults.temporary.IsEmpty()&&!PathFileExists(faults.temporary),"cancel retires its uniquely owned staging file");}
    cancel=true;services::AtomicWriteFaults faults;services::atomicWriteFaults=&faults;{core::CancellationScope scope(cancel);check(!services::WriteBytes(path,replacement,error)&&faults.temporary.IsEmpty(),"already cancelled output creates no staging file");}services::atomicWriteFaults=nullptr;
    cancel=false;faults.checkpoint=[&](int at){if(at==3)cancel=true;};services::atomicWriteFaults=&faults;bool saved=false;{core::CancellationScope scope(cancel);saved=services::WriteBytes(path,replacement,error);}services::atomicWriteFaults=nullptr;
    check(saved&&cancel&&services::ReadBytes(path,read,error)&&read==replacement,"cancel observed after successful publish does not claim rollback");
    for(bool promote:{false,true}){services::AtomicWriteFaults failure;failure.write=promote?0:ERROR_DISK_FULL;failure.promote=promote?ERROR_ACCESS_DENIED:0;services::atomicWriteFaults=&failure;const bool ok=services::WriteBytes(path,old,error);services::atomicWriteFaults=nullptr;check(!ok&&services::ReadBytes(path,read,error)&&read==replacement&&!PathFileExists(failure.temporary),"write/publish failure retains last good output and removes owned staging");}
}
